{"sceneId":"a49d47a5-d6f5-4661-bc48-f13066e000e2","name":"99.9% Uptime SLA Stat Card","code":"const { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } = window.Remotion;

// ACT 1 (0–30): Card springs in from scale 0.85 → 1.0, all content enters together
// ACT 2 (30–90): Calm hold — heartbeat pulse, border glow, fill bar sweeps, ambient breathe

export default function Scene_mt8hxzvn() {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // === CARD ENTRANCE (spring) ===
  const cardSpring = spring({
    frame,
    fps: 30,
    config: { damping: 22, stiffness: 160, mass: 1 },
  });
  const cardScale = interpolate(cardSpring, [0, 1], [0.85, 1]);
  const cardOpacity = interpolate(frame, [0, 18], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });

  // === HEARTBEAT PULSE (slow, calm) ===
  // Period ~90 frames = 3s, very subtle
  const heartbeat = Math.sin((frame / 90) * Math.PI * 2);
  const pulseScale = 1 + heartbeat * 0.005;

  // === BORDER GLOW PULSE ===
  const glowIntensity = 0.3 + heartbeat * 0.12;
  const outerGlow = 18 + heartbeat * 8;
  const outerGlow2 = 40 + heartbeat * 14;

  // === FILL BAR (sweeps left→right over frames 20–60) ===
  const fillProgress = interpolate(frame, [20, 62], [0, 0.999], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.bezier(0.4, 0, 0.2, 1),
  });

  // === CONTENT ENTRANCE (stagger slightly within card spring) ===
  const labelOpacity = interpolate(frame, [8, 22], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const statOpacity = interpolate(frame, [12, 28], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const statY = interpolate(frame, [12, 28], [12, 0], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const subOpacity = interpolate(frame, [18, 32], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const chipsOpacity = interpolate(frame, [24, 40], [0, 1], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  const chipsY = interpolate(frame, [24, 40], [8, 0], {
    extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });

  // === TEXT GLOW PULSE ===
  const textGlowV = 18 + heartbeat * 6;
  const textGlowC = 14 + heartbeat * 5;

  const cardW = width * 0.65;

  return (
    <AbsoluteFill style={{
      backgroundColor: 'transparent',
      fontFamily: 'Inter, sans-serif',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
