          borderRadius: 20,
          border: `1px solid rgba(111,71,245,${glowIntensity})`,
          boxShadow: `
            0 0 ${outerGlow}px rgba(111,71,245,0.35),
            0 0 ${outerGlow2}px rgba(6,182,212,0.18),
            0 24px 80px rgba(0,0,0,0.7),
            inset 0 1px 0 rgba(255,255,255,0.04)
          `,
          overflow: 'hidden',
          padding: '36px 44px 28px 44px',
          display: 'flex',
          flexDirection: 'column',
          gap: 0,
        }}>

          {/* TOP LABEL + SEPARATOR */}
          <div style={{ opacity: labelOpacity, marginBottom: 18 }}>
            <div style={{
              fontSize: 11,
              fontWeight: 600,
              letterSpacing: '2px',
              color: '#475569',
              textTransform: 'uppercase',
              marginBottom: 12,
            }}>
              Service Level Agreement
            </div>
            <div style={{
              height: 1,
              background: 'linear-gradient(90deg, rgba(111,71,245,0.5) 0%, rgba(6,182,212,0.3) 60%, transparent 100%)',
            }} />
          </div>

          {/* MASSIVE STAT */}
          <div style={{
            opacity: statOpacity,
            transform: `translateY(${statY}px)`,
            textAlign: 'center',
            marginBottom: 10,
          }}>
            <div style={{
              fontSize: 140,
              fontWeight: 900,
              lineHeight: 1,
              background: 'linear-gradient(90deg, #8b5cf6 0%, #06b6d4 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text',
              filter: `drop-shadow(0 0 ${textGlowV}px rgba(139,92,246,0.7)) drop-shadow(0 0 ${textGlowC}px rgba(6,182,212,0.5))`,
              letterSpacing: '-2px',
            }}>
              99.9%
            </div>
          </div>

          {/* UPTIME LABEL */}
          <div style={{
            opacity: subOpacity,
            textAlign: 'center',
            marginBottom: 6,
          }}>
            <div style={{
              fontSize: 28,
              fontWeight: 600,
              color: '#ffffff',
              letterSpacing: '-0.3px',
            }}>
              Uptime SLA
            </div>
          </div>

          {/* SUBTITLE */}
          <div style={{
            opacity: subOpacity,
            textAlign: 'center',
            marginBottom: 28,
          }}>
            <div style={{
              fontSize: 16,
              fontWeight: 400,
              color: '#94a3b8',
              letterSpacing: '0.1px',
            }}>
              Guaranteed availability. Every month.
            </div>
          </div>

          {/* PROOF CHIPS */}
          <div style={{
            opacity: chipsOpacity,
            transform: `translateY(${chipsY}px)`,
            display: 'flex',
            gap: 10,
            justifyContent: 'center',
            marginBottom: 24,
          }}>
            {[
              'Monitored 24/7',
              'Auto-failover',
              '30-day SLA credit',
            ].map((label, i) => (
              <div key={i} style={{
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                background: '#0d1525',
                border: '1px solid rgba(34,197,94,0.3)',
                borderRadius: 20,
                padding: '6px 14px',
                boxShadow: '0 0 8px rgba(34,197,94,0.08)',
              }}>
                <div style={{
                  width: 6,
                  height: 6,
                  borderRadius: '50%',
                  background: '#22c55e',
                  boxShadow: '0 0 6px rgba(34,197,94,0.8)',
                  flexShrink: 0,
                }} />
                <span style={{
                  fontSize: 11,
                  fontWeight: 600,
                  color: '#86efac',
                  whiteSpace: 'nowrap',
                }}>
                  {label}
                </span>
              </div>
            ))}
          </div>

          {/* ANIMATED FILL BAR */}
          <div style={{ opacity: subOpacity }}>
            {/* Track */}
            <div style={{
              height: 4,
              background: 'rgba(255,255,255,0.06)',
              borderRadius: 4,
              overflow: 'hidden',
              position: 'relative',
            }}>
              {/* Fill */}
              <div style={{
                position: 'absolute',
                left: 0,
                top: 0,
                height: '100%',
                width: `${fillProgress * 100}%`,
                background: 'linear-gradient(90deg, #06b6d4 0%, #8b5cf6 100%)',
                borderRadius: 4,
                boxShadow: `0 0 8px rgba(6,182,212,0.6), 0 0 16px rgba(139,92,246,0.4)`,
              }} />
              {/* Tip glow dot */}
              {fillProgress > 0.01 && (
                <div style={{
                  position: 'absolute',
                  top: '50%',
                  left: `${fillProgress * 100}%`,
                  transform: 'translate(-50%, -50%)',
                  width: 8,
                  height: 8,
                  borderRadius: '50%',
                  background: '#06b6d4',
                  boxShadow: '0 0 10px rgba(6,182,212,0.9), 0 0 20px rgba(6,182,212,0.5)',
                }} />
              )}
            </div>
            {/* Bar label */}
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              marginTop: 6,
            }}>
              <span style={{ fontSize: 9, color: '#334155', fontWeight: 600, letterSpacing: '0.5px' }}>0%</span>
              <span style={{ fontSize: 9, color: '#06b6d4', fontWeight: 700, letterSpacing: '0.5px' }}>
                {(fillProgress * 100).toFixed(1)}% uptime this month
              </span>
              <span style={{ fontSize: 9, color: '#334155', fontWeight: 600, letterSpacing: '0.5px' }}>100%</span>
            </div>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
}

